const state = await api("/api/state");
const productByName = new Map(state.products.map((product) => [product.name, product]));
const existing = new Set(state.productMarketingEntries.map((entry) =>
  [entry.scope, entry.category, entry.product, entry.text].join("\u001f")));
const additions = [];
for (const [product, copies] of Object.entries(data)) {
  const record = productByName.get(product);
  if (!record) throw new Error(`产品不存在：${product}`);
  for (const copy of copies) {
    const entry = { scope: "product", category: record.category, product, enabled: true, ...copy };
    const key = [entry.scope, entry.category, entry.product, entry.text].join("\u001f");
    if (!existing.has(key)) additions.push(entry);
  }
}
await api("/api/product-marketing/save", {
  method: "POST",
  body: JSON.stringify({ entries: [...state.productMarketingEntries, ...additions] }),
});
console.log(JSON.stringify({ added: additions.length, products: Object.keys(data).length }, null, 2));
